    91  // Returns whether the class can handle the format of the given file.
    92  bool XFileImporter::CanRead( const std::string& pFile, IOSystem* pIOHandler, bool checkSig) const {
    93      std::string extension = GetExtension(pFile);
    94      if(extension == "x") {
    95          return true;
    96      }
    97      if (!extension.length() || checkSig) {
    98          uint32_t token[1];
    99          token[0] = AI_MAKE_MAGIC("xof ");
   100          return CheckMagicToken(pIOHandler,pFile,token,1,0);
   101      }
   102      return false;
   103  }
