   206  // Recursively creates scene nodes from the imported hierarchy.
   207  aiNode* XFileImporter::CreateNodes( aiScene* pScene, aiNode* pParent, const XFile::Node* pNode) {
   208      if ( !pNode ) {
   209          return nullptr;
   210      }
   211
   212      // create node
   213      aiNode* node = new aiNode;
   214      node->mName.length = (ai_uint32)pNode->mName.length();
   215      node->mParent = pParent;
   216      memcpy( node->mName.data, pNode->mName.c_str(), pNode->mName.length());
   217      node->mName.data[node->mName.length] = 0;
   218      node->mTransformation = pNode->mTrafoMatrix;
   219
   220      // convert meshes from the source node
   221      CreateMeshes( pScene, node, pNode->mMeshes);
   222
   223      // handle childs
   224      if( !pNode->mChildren.empty() ) {
   225          node->mNumChildren = (unsigned int)pNode->mChildren.size();
   226          node->mChildren = new aiNode* [node->mNumChildren];
   227
   228          for ( unsigned int a = 0; a < pNode->mChildren.size(); ++a ) {
   229              node->mChildren[ a ] = CreateNodes( pScene, node, pNode->mChildren[ a ] );
   230          }
   231      }
   232
   233      return node;
   234  }
