   245      for( unsigned int a = 0; a < pMeshes.size(); ++a ) {
   246          XFile::Mesh* sourceMesh = pMeshes[a];
   247          if ( nullptr == sourceMesh ) {
   248              continue;
   249          }
   250
   251          // first convert its materials so that we can find them with their index afterwards
   252          ConvertMaterials( pScene, sourceMesh->mMaterials);
   253
   254          unsigned int numMaterials = std::max( (unsigned int)sourceMesh->mMaterials.size(), 1u);
   255          for( unsigned int b = 0; b < numMaterials; ++b ) {
   256              // collect the faces belonging to this material
   257              std::vector<unsigned int> faces;
   258              unsigned int numVertices = 0;
   259              if( !sourceMesh->mFaceMaterials.empty() ) {
   260                  // if there is a per-face material defined, select the faces with the corresponding material
   261                  for( unsigned int c = 0; c < sourceMesh->mFaceMaterials.size(); ++c ) {
   262                      if( sourceMesh->mFaceMaterials[c] == b) {
   263                          faces.push_back( c);
   264                          numVertices += (unsigned int)sourceMesh->mPosFaces[c].mIndices.size();
   265                      }
   266                  }
   267              } else {
   268                  // if there is no per-face material, place everything into one mesh
   269                  for( unsigned int c = 0; c < sourceMesh->mPosFaces.size(); ++c ) {
   270                      faces.push_back( c);
   271                      numVertices += (unsigned int)sourceMesh->mPosFaces[c].mIndices.size();
   272                  }
   273              }
   274
   275              // no faces/vertices using this material? strange...
   276              if ( numVertices == 0 ) {
   277                  continue;
   278              }
   279
   280              // create a submesh using this material
   281              aiMesh* mesh = new aiMesh;
   282              meshes.push_back( mesh);
   283
   284              // find the material in the scene's material list. Either own material
   285              // or referenced material, it should already have a valid index
   286              if( !sourceMesh->mFaceMaterials.empty() ) {
   287                  mesh->mMaterialIndex = static_cast<unsigned int>(sourceMesh->mMaterials[b].sceneIndex);
   288              } else {
   289                  mesh->mMaterialIndex = 0;
   290              }
   291
   292              // Create properly sized data arrays in the mesh. We store unique vertices per face,
   293              // as specified
   294              mesh->mNumVertices = numVertices;
   295              mesh->mVertices = new aiVector3D[numVertices];
   296              mesh->mNumFaces = (unsigned int)faces.size();
   297              mesh->mFaces = new aiFace[mesh->mNumFaces];
   298
   299              // name
   300              mesh->mName.Set(sourceMesh->mName);
   301
   302              // normals?
   303              if ( sourceMesh->mNormals.size() > 0 ) {
   304                  mesh->mNormals = new aiVector3D[ numVertices ];
   305              }
   306              // texture coords
   307              for( unsigned int c = 0; c < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++c ) {
   308                  if ( !sourceMesh->mTexCoords[ c ].empty() ) {
   309                      mesh->mTextureCoords[ c ] = new aiVector3D[ numVertices ];
   310                  }
   311              }
   312              // vertex colors
   313              for( unsigned int c = 0; c < AI_MAX_NUMBER_OF_COLOR_SETS; ++c ) {
   314                  if ( !sourceMesh->mColors[ c ].empty() ) {
   315                      mesh->mColors[ c ] = new aiColor4D[ numVertices ];
   316                  }
   317              }
   318
   319              // now collect the vertex data of all data streams present in the imported mesh
   320              unsigned int newIndex( 0 );
   321              std::vector<unsigned int> orgPoints; // from which original point each new vertex stems
   322              orgPoints.resize( numVertices, 0);
   323
   324              for( unsigned int c = 0; c < faces.size(); ++c ) {
   325                  unsigned int f = faces[c]; // index of the source face
   326                  const XFile::Face& pf = sourceMesh->mPosFaces[f]; // position source face
   327
   328                  // create face. either triangle or triangle fan depending on the index count
   329                  aiFace& df = mesh->mFaces[c]; // destination face
   330                  df.mNumIndices = (unsigned int)pf.mIndices.size();
   331                  df.mIndices = new unsigned int[ df.mNumIndices];
   332
   333                  // collect vertex data for indices of this face
   334                  for( unsigned int d = 0; d < df.mNumIndices; ++d ) {
   335                      df.mIndices[ d ] = newIndex;
   336                      const unsigned int newIdx( pf.mIndices[ d ] );
   337                      if ( newIdx > sourceMesh->mPositions.size() ) {
   338                          continue;
   339                      }
   340
   341                      orgPoints[newIndex] = pf.mIndices[d];
   342
   343                      // Position
   344                      mesh->mVertices[newIndex] = sourceMesh->mPositions[pf.mIndices[d]];
   345                      // Normal, if present
   346                      if ( mesh->HasNormals() ) {
   347                          if ( sourceMesh->mNormFaces[ f ].mIndices.size() > d ) {
   348                              const size_t idx( sourceMesh->mNormFaces[ f ].mIndices[ d ] );
   349                              mesh->mNormals[ newIndex ] = sourceMesh->mNormals[ idx ];
   350                          }
   351                      }
   352
   353                      // texture coord sets
   354                      for( unsigned int e = 0; e < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++e ) {
   355                          if( mesh->HasTextureCoords( e)) {
   356                              aiVector2D tex = sourceMesh->mTexCoords[e][pf.mIndices[d]];
   357                              mesh->mTextureCoords[e][newIndex] = aiVector3D( tex.x, 1.0f - tex.y, 0.0f);
   358                          }
   359                      }
   360                      // vertex color sets
   361                      for ( unsigned int e = 0; e < AI_MAX_NUMBER_OF_COLOR_SETS; ++e ) {
   362                          if ( mesh->HasVertexColors( e ) ) {
   363                              mesh->mColors[ e ][ newIndex ] = sourceMesh->mColors[ e ][ pf.mIndices[ d ] ];
   364                          }
   365                      }
   366
   367                      newIndex++;
   368                  }
   369              }
   370
   371              // there should be as much new vertices as we calculated before
   372              ai_assert( newIndex == numVertices);
   373
   374              // convert all bones of the source mesh which influence vertices in this newly created mesh
   375              const std::vector<XFile::Bone>& bones = sourceMesh->mBones;
   376              std::vector<aiBone*> newBones;
   377              for( unsigned int c = 0; c < bones.size(); ++c ) {
   378                  const XFile::Bone& obone = bones[c];
   379                  // set up a vertex-linear array of the weights for quick searching if a bone influences a vertex
   380                  std::vector<ai_real> oldWeights( sourceMesh->mPositions.size(), 0.0);
   381                  for ( unsigned int d = 0; d < obone.mWeights.size(); ++d ) {
   382                      oldWeights[ obone.mWeights[ d ].mVertex ] = obone.mWeights[ d ].mWeight;
   383                  }
   384
   385                  // collect all vertex weights that influence a vertex in the new mesh
   386                  std::vector<aiVertexWeight> newWeights;
   387                  newWeights.reserve( numVertices);
   388                  for( unsigned int d = 0; d < orgPoints.size(); ++d ) {
   389                      // does the new vertex stem from an old vertex which was influenced by this bone?
   390                      ai_real w = oldWeights[orgPoints[d]];
   391                      if ( w > 0.0 ) {
   392                          newWeights.push_back( aiVertexWeight( d, w ) );
   393                      }
   394                  }
   395
   396                  // if the bone has no weights in the newly created mesh, ignore it
   397                  if ( newWeights.empty() ) {
   398                      continue;
   399                  }
   400
   401                  // create
   402                  aiBone* nbone = new aiBone;
   403                  newBones.push_back( nbone);
   404                  // copy name and matrix
   405                  nbone->mName.Set( obone.mName);
   406                  nbone->mOffsetMatrix = obone.mOffsetMatrix;
   407                  nbone->mNumWeights = (unsigned int)newWeights.size();
   408                  nbone->mWeights = new aiVertexWeight[nbone->mNumWeights];
   409                  for ( unsigned int d = 0; d < newWeights.size(); ++d ) {
   410                      nbone->mWeights[ d ] = newWeights[ d ];
   411                  }
   412              }
   413
   414              // store the bones in the mesh
   415              mesh->mNumBones = (unsigned int)newBones.size();
   416              if( !newBones.empty()) {
   417                  mesh->mBones = new aiBone*[mesh->mNumBones];
   418                  std::copy( newBones.begin(), newBones.end(), mesh->mBones);
   419              }
   420          }
   421      }
   422
   423      // reallocate scene mesh array to be large enough
   424      aiMesh** prevArray = pScene->mMeshes;
   425      pScene->mMeshes = new aiMesh*[pScene->mNumMeshes + meshes.size()];
   426      if( prevArray) {
   427          memcpy( pScene->mMeshes, prevArray, pScene->mNumMeshes * sizeof( aiMesh*));
   428          delete [] prevArray;
   429      }
   430
   431      // allocate mesh index array in the node
   432      pNode->mNumMeshes = (unsigned int)meshes.size();
   433      pNode->mMeshes = new unsigned int[pNode->mNumMeshes];
   434
   435      // store all meshes in the mesh library of the scene and store their indices in the node
   436      for( unsigned int a = 0; a < meshes.size(); a++) {
   437          pScene->mMeshes[pScene->mNumMeshes] = meshes[a];
   438          pNode->mMeshes[a] = pScene->mNumMeshes;
   439          pScene->mNumMeshes++;
   440      }
   441  }
