   443  // ------------------------------------------------------------------------------------------------
   444  // Converts the animations from the given imported data and creates them in the scene.
   445  void XFileImporter::CreateAnimations( aiScene* pScene, const XFile::Scene* pData) {
   446      std::vector<aiAnimation*> newAnims;
   447
   448      for( unsigned int a = 0; a < pData->mAnims.size(); ++a ) {
   449          const XFile::Animation* anim = pData->mAnims[a];
   450          // some exporters mock me with empty animation tags.
   451          if ( anim->mAnims.empty() ) {
   452              continue;
   453          }
   454
   455          // create a new animation to hold the data
   456          aiAnimation* nanim = new aiAnimation;
   457          newAnims.push_back( nanim);
   458          nanim->mName.Set( anim->mName);
   459          // duration will be determined by the maximum length
   460          nanim->mDuration = 0;
   461          nanim->mTicksPerSecond = pData->mAnimTicksPerSecond;
   462          nanim->mNumChannels = (unsigned int)anim->mAnims.size();
   463          nanim->mChannels = new aiNodeAnim*[nanim->mNumChannels];
   464
   465          for( unsigned int b = 0; b < anim->mAnims.size(); ++b ) {
   466              const XFile::AnimBone* bone = anim->mAnims[b];
   467              aiNodeAnim* nbone = new aiNodeAnim;
   468              nbone->mNodeName.Set( bone->mBoneName);
   469              nanim->mChannels[b] = nbone;
   470
   471              // key-frames are given as combined transformation matrix keys
   472              if( !bone->mTrafoKeys.empty() )
   473              {
   474                  nbone->mNumPositionKeys = (unsigned int)bone->mTrafoKeys.size();
   475                  nbone->mPositionKeys = new aiVectorKey[nbone->mNumPositionKeys];
   476                  nbone->mNumRotationKeys = (unsigned int)bone->mTrafoKeys.size();
   477                  nbone->mRotationKeys = new aiQuatKey[nbone->mNumRotationKeys];
   478                  nbone->mNumScalingKeys = (unsigned int)bone->mTrafoKeys.size();
   479                  nbone->mScalingKeys = new aiVectorKey[nbone->mNumScalingKeys];
   480
   481                  for( unsigned int c = 0; c < bone->mTrafoKeys.size(); ++c)  {
   482                      // deconstruct each matrix into separate position, rotation and scaling
   483                      double time = bone->mTrafoKeys[c].mTime;
   484                      aiMatrix4x4 trafo = bone->mTrafoKeys[c].mMatrix;
   485
   486                      // extract position
   487                      aiVector3D pos( trafo.a4, trafo.b4, trafo.c4);
   488
   489                      nbone->mPositionKeys[c].mTime = time;
   490                      nbone->mPositionKeys[c].mValue = pos;
   491
   492                      // extract scaling
   493                      aiVector3D scale;
   494                      scale.x = aiVector3D( trafo.a1, trafo.b1, trafo.c1).Length();
   495                      scale.y = aiVector3D( trafo.a2, trafo.b2, trafo.c2).Length();
   496                      scale.z = aiVector3D( trafo.a3, trafo.b3, trafo.c3).Length();
   497                      nbone->mScalingKeys[c].mTime = time;
   498                      nbone->mScalingKeys[c].mValue = scale;
   499
   500                      // reconstruct rotation matrix without scaling
   501                      aiMatrix3x3 rotmat(
   502                          trafo.a1 / scale.x, trafo.a2 / scale.y, trafo.a3 / scale.z,
   503                          trafo.b1 / scale.x, trafo.b2 / scale.y, trafo.b3 / scale.z,
   504                          trafo.c1 / scale.x, trafo.c2 / scale.y, trafo.c3 / scale.z);
   505
   506                      // and convert it into a quaternion
   507                      nbone->mRotationKeys[c].mTime = time;
   508                      nbone->mRotationKeys[c].mValue = aiQuaternion( rotmat);
   509                  }
   510
   511                  // longest lasting key sequence determines duration
   512                  nanim->mDuration = std::max( nanim->mDuration, bone->mTrafoKeys.back().mTime);
   513              } else {
   514                  // separate key sequences for position, rotation, scaling
   515                  nbone->mNumPositionKeys = (unsigned int)bone->mPosKeys.size();
   516                  if (nbone->mNumPositionKeys != 0) {
   517                      nbone->mPositionKeys = new aiVectorKey[nbone->mNumPositionKeys];
   518                      for( unsigned int c = 0; c < nbone->mNumPositionKeys; ++c ) {
   519                          aiVector3D pos = bone->mPosKeys[c].mValue;
   520
   521                          nbone->mPositionKeys[c].mTime = bone->mPosKeys[c].mTime;
   522                          nbone->mPositionKeys[c].mValue = pos;
   523                      }
   524                  }
   525
   526                  // rotation
   527                  nbone->mNumRotationKeys = (unsigned int)bone->mRotKeys.size();
   528                  if (nbone->mNumRotationKeys != 0) {
   529                      nbone->mRotationKeys = new aiQuatKey[nbone->mNumRotationKeys];
   530                      for( unsigned int c = 0; c < nbone->mNumRotationKeys; ++c ) {
   531                          aiMatrix3x3 rotmat = bone->mRotKeys[c].mValue.GetMatrix();
   532
   533                          nbone->mRotationKeys[c].mTime = bone->mRotKeys[c].mTime;
   534                          nbone->mRotationKeys[c].mValue = aiQuaternion( rotmat);
   535                          nbone->mRotationKeys[c].mValue.w *= -1.0f; // needs quat inversion
   536                      }
   537                  }
   538
   539                  // scaling
   540                  nbone->mNumScalingKeys = (unsigned int)bone->mScaleKeys.size();
   541                  if (nbone->mNumScalingKeys != 0) {
   542                      nbone->mScalingKeys = new aiVectorKey[nbone->mNumScalingKeys];
   543                      for( unsigned int c = 0; c < nbone->mNumScalingKeys; c++)
   544                          nbone->mScalingKeys[c] = bone->mScaleKeys[c];
   545                  }
   546
   547                  // longest lasting key sequence determines duration
   548                  if( bone->mPosKeys.size() > 0)
   549                      nanim->mDuration = std::max( nanim->mDuration, bone->mPosKeys.back().mTime);
   550                  if( bone->mRotKeys.size() > 0)
   551                      nanim->mDuration = std::max( nanim->mDuration, bone->mRotKeys.back().mTime);
   552                  if( bone->mScaleKeys.size() > 0)
   553                      nanim->mDuration = std::max( nanim->mDuration, bone->mScaleKeys.back().mTime);
   554              }
   555          }
   556      }
   557
   558      // store all converted animations in the scene
   559      if( newAnims.size() > 0)
   560      {
   561          pScene->mNumAnimations = (unsigned int)newAnims.size();
   562          pScene->mAnimations = new aiAnimation* [pScene->mNumAnimations];
   563          for( unsigned int a = 0; a < newAnims.size(); a++)
   564              pScene->mAnimations[a] = newAnims[a];
   565      }
   566  }
